function RowGrouping({
  caption = "{{caption}}",
  accent = "{{accent}}",
  groupBy = "{{groupBy}}",
  collapsedGroup = {{collapsedGroup}},
  showCounts = {{showCounts}},
}) {
  const cell = { padding: "9px 14px", borderBottom: "1px solid #24143020", whiteSpace: "nowrap" };
  const groupRow = { background: "#24143012", fontWeight: 600, fontSize: 12, textTransform: "uppercase", letterSpacing: ".04em", padding: "9px 14px" };
  const groups = [
    { name: "EMEA", collapsible: true, rows: [["#1042", "A. Whitfield", "Shipped", "£64.00"], ["#1041", "R. Okafor", "Processing", "£128.50"], ["#1038", "L. Duarte", "Shipped", "£96.20"]] },
    { name: "Americas", collapsible: false, rows: [["#1040", "M. Iqbal", "Shipped", "£22.00"], ["#1039", "S. Novak", "Refunded", "£40.00"]] },
  ];
  return (
    <div style={{ maxWidth: 480, borderRadius: 10, border: "1px solid #24143020", overflow: "hidden", font: "14px system-ui, sans-serif", color: "#241430", background: "#FAF7F2" }}>
      <div style={{ overflowX: "auto" }}>
        <table style={{ borderCollapse: "collapse", width: "100%" }}>
          <caption style={{ textAlign: "left", fontWeight: 600, padding: "10px 14px" }}>{caption} — grouped by {groupBy}</caption>
          <thead>
            <tr style={{ background: accent, color: "#FAF7F2" }}>
              {["Order", "Customer", "Status", "Total"].map((h) => <th key={h} scope="col" style={cell}>{h}</th>)}
            </tr>
          </thead>
          <tbody>
            {groups.flatMap((g) => {
              const header = (
                <tr key={`${g.name}-header`}><td colSpan={4} style={groupRow}>{g.name}{showCounts && <span style={{ fontWeight: 400, textTransform: "none", color: "#241430a0" }}> ({g.rows.length})</span>}</td></tr>
              );
              const dataRows = (g.collapsible && collapsedGroup) ? [] : g.rows.map((row) => (
                <tr key={row[0]}>{row.map((c, j) => <td key={j} style={cell}>{c}</td>)}</tr>
              ));
              return [header, ...dataRows];
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}
